using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.GameStates;
using DG.Tweening;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class DiceInstance : ActionInstance
{
	[Header("Components Dice Instance")]
	[SerializeField]
	private ListDiceInstanceEvent OnDiscardUsedDices;

	[SerializeField]
	private ActionInstanceReference chooseDiceActionInstanceReference;

	[SerializeField]
	private DiceRolling diceRolling;

	[SerializeField]
	private DiceMovement diceMovement;

	[SerializeField]
	private DiceVisuals diceVisuals;

	[Header("Destroy Die VFX")]
	[SerializeField]
	private GameObject destroyDieVFXPrefab;

	[SerializeField]
	private EventReference destroyDiceSFX;

	[Header("Enemies and Companions")]
	[SerializeField]
	private float diceRotationX;

	[Header("Sea Requiem")]
	[SerializeField]
	private SeaRequiemAction seaRequiemAction;

	[Header("Runtime")]
	[SerializeField]
	private DiceState diceState;

	[SerializeField]
	private Dice dice;

	[SerializeField]
	private Dice originalDice;

	[SerializeField]
	private int rolledDiceFaceIndex;

	private bool hideDiceFace;

	public DiceTargetCastSpaceInstance diceTargetCastSpaceInstance;

	private System.Action afterGoBackToOriginalPositionAction;

	public System.Action AfterDiscardAction;

	private Vector2 originalPosition;

	private bool ignoreNextDisposeAction;

	public ActionInstanceReference ChooseDiceActionInstanceReference => chooseDiceActionInstanceReference;

	public DiceRolling DiceRolling => diceRolling;

	public DiceMovement DiceMovement => diceMovement;

	public DiceVisuals DiceVisuals => diceVisuals;

	public DiceState DiceState => diceState;

	public Dice Dice => dice;

	public Dice OriginalDice => originalDice;

	public int RolledDiceFaceIndex => rolledDiceFaceIndex;

	public bool HideDiceFace => hideDiceFace;

	public DiceTargetCastSpaceInstance DiceTargetCastSpaceInstance => diceTargetCastSpaceInstance;

	public bool ConsumeIgnoreNextDisposeAction()
	{
		bool result = ignoreNextDisposeAction;
		ignoreNextDisposeAction = false;
		return result;
	}

	public void OnPlayerCompletelyCorruptedAnimation()
	{
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
	}

	public override void OnMouseOver()
	{
		if (hideDiceFace)
		{
			OnMouseOverNoActionDescriptionPanel();
		}
		else if (!mouseOver && !dragging && (diceState == DiceState.OnHand || diceState == DiceState.OnDiceTargetCastSpace || diceState == DiceState.OnBattleActionCastSpace))
		{
			base.OnMouseOver();
		}
	}

	protected override void Awake()
	{
		cameraEnum = CameraEnum.DiceTossing;
		base.Awake();
	}

	public void Initialize(Dice dice, ActionInstanceData actionInstanceData, GameObject actionOwner = null, DiceOwnerEnum diceOwnerEnum = DiceOwnerEnum.PLAYER, bool hideDiceFace = false)
	{
		this.dice = dice;
		base.actionOwner = actionOwner;
		base.diceOwnerEnum = diceOwnerEnum;
		this.hideDiceFace = hideDiceFace;
		ResetDiceTargetCastSpaceInstance();
		actionEnabled = true;
		dragging = false;
		InitializeActionInstance(actionInstanceData);
		disableDiscard = false;
		diceVisuals.Initialize(dice, hideDiceFace);
		ignoreNextDisposeAction = false;
	}

	public void SetupDiceToRoll()
	{
		SetDiceState(DiceState.WaitingToBeRolled);
		diceRolling.SetupDiceToRoll();
		diceVisuals.SetupDiceToRoll();
		diceMovement.SetupDiceToRoll();
		dragging = false;
	}

	public void SetupDiceRollRepairAction()
	{
		SetDiceState(DiceState.WaitingToBeRolled);
		diceRolling.SetupDiceToRoll();
	}

	private bool DiceActionSelectedCheck(bool joystick)
	{
		if (base.actionFace.BattleAction.GetDiceActionLogic(base.actionFace.ModifiedActionValue) == null && base.isOnChooseActionState)
		{
			Debug.Log("DICE INSTANCE: DiceActionLogic null && not ChooseDiceState && not ChoosePlayerDiceState");
			return false;
		}
		if (!base.isOnChooseActionState && !ChooseDiceStateCheckCondition())
		{
			return false;
		}
		if (base.isOnChooseActionState)
		{
			if (!ActionSelectedCheckConditionToBeCastedWithActionValue(diceOwnerEnum == DiceOwnerEnum.PLAYER))
			{
				return false;
			}
			if (joystick && base.actionFace.BattleAction.GetDiceActionLogic(base.actionFace.ModifiedActionValue).ActionGameState == ReferenceSingleton<GameStateManager>.Instance.DiceTargetCastState)
			{
				ActionSelected();
				return false;
			}
		}
		(actionInstanceOutlineHandler as DiceInstanceOutlineHandler).SetTransitionOutlineLayer();
		SetDiceState(DiceState.Dragged);
		SetupDiceToStartFollowingMouse();
		actionInstanceOutlineHandler.StopShakeCoroutine();
		if (!base.isOnChooseActionState)
		{
			ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(this);
		}
		return true;
	}

	public void SetupDiceToStartFollowingMouse()
	{
		diceMovement.StartFollowingMouseRotationAnimation();
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
	}

	public bool ChooseDiceStateCheckCondition()
	{
		if (!(chooseDiceActionInstanceReference.Value.ActionFace.BattleAction as ChooseDiceAction).CheckCondition(this))
		{
			PlayCantUseActionFeedback();
			return false;
		}
		return true;
	}

	public void DiceRemovedFromDiceTargetCastSpaceInstance()
	{
		Debug.Log("DICE INSTANCE: diceTargetCastSpaceInstance " + diceTargetCastSpaceInstance);
		diceTargetCastSpaceInstance.ActionRemoved(this);
		ResetDiceTargetCastSpaceInstance();
	}

	public override void ActionDroppedOnBattleActionCastSpace()
	{
		base.ActionDroppedOnBattleActionCastSpace();
		SetDiceState(DiceState.OnBattleActionCastSpace);
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
	}

	public void DicePlacedOnDiceTargetCastSpace(DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		this.diceTargetCastSpaceInstance = diceTargetCastSpaceInstance;
		Debug.Log("DICE INSTANCE PLACED: diceTargetCastSpaceInstance" + diceTargetCastSpaceInstance);
		SetDiceState(DiceState.OnDiceTargetCastSpace);
		dragging = false;
		ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
		actionFaceImage.raycastTarget = true;
		actionInstanceOutlineHandler.ToggleOutline(toggle: true);
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			StoreTrail();
		});
	}

	public override bool StartFollowingMouse()
	{
		if (!CanDrag())
		{
			return false;
		}
		if (diceTargetCastSpaceInstance == null)
		{
			originalPosition = base.transform.position;
		}
		if (diceTargetCastSpaceInstance != null)
		{
			DiceRemovedFromDiceTargetCastSpaceInstance();
		}
		if (!DiceActionSelectedCheck(joystick: false))
		{
			return false;
		}
		return base.StartFollowingMouse();
	}

	public override void StopFollowingMouse()
	{
		base.StopFollowingMouse();
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
	}

	public bool CheckPointAndClickDraggableStates(GameState gameStateToCheck, bool playCantUseActionFeedback)
	{
		if (!CanDrag(gameStateToCheck))
		{
			if (playCantUseActionFeedback)
			{
				PlayCantUseActionFeedback();
			}
			return false;
		}
		return true;
	}

	public void ChooseDiceStateFirstDiceChosen(Vector3 diceTargetCastSpaceInstancePosition)
	{
		actionFaceImage.raycastTarget = false;
		Vector3 diceOnTargetCastSpacePositionAdjustment = ReferenceSingleton<InputManager>.Instance.GetDiceOnTargetCastSpacePositionAdjustment(diceTargetCastSpaceInstancePosition, diceInstance: true);
		diceMovement.StartFollowingMouseRotationAnimation();
		base.transform.DOMove(diceOnTargetCastSpacePositionAdjustment, ReferenceSingleton<InputManager>.Instance.ActionInstanceMovementDuration);
		SetDiceState(DiceState.OnDiceTargetCastSpace);
	}

	public override bool JoystickActionSelected()
	{
		if (!CanDrag())
		{
			return false;
		}
		if (!DiceActionSelectedCheck(joystick: true))
		{
			return false;
		}
		return base.JoystickActionSelected();
	}

	public override void JoystickActionCanceled()
	{
		base.JoystickActionCanceled();
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
	}

	public override void GoBackToOriginalPositionAnimation(bool returningToHandAfterDrag = false, System.Action afterGoBackToOriginalPositionAction = null)
	{
		base.GoBackToOriginalPositionAnimation(returningToHandAfterDrag, afterGoBackToOriginalPositionAction);
		this.afterGoBackToOriginalPositionAction = afterGoBackToOriginalPositionAction;
		if (base.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			if (returningToHandAfterDrag)
			{
				SetDiceState(DiceState.ReturningToHandAfterDrag);
			}
			else
			{
				SetDiceState(DiceState.ReturningToHandAfterTargetSpace);
			}
		}
		else
		{
			PlayGoBackToOriginalPositionAnimationCompanionsAndEnemies(diceRotationX, 0f);
		}
	}

	private void PlayGoBackToOriginalPositionAnimationCompanionsAndEnemies(float rotationX, float rotationZ)
	{
		diceMovement.PlayGoBackToOriginalPositionAnimation(originalPosition, 0.2f, endDragAnimCurve, rotationX, rotationZ, delegate
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
			{
				AfterGoBackToOriginalPositionAnimation(afterGoBackToOriginalPositionAction);
				afterGoBackToOriginalPositionAction = null;
			});
		});
	}

	public void PlayGoBackToHandFromDiceCastSpaceOrFromDragAnimation(Vector3 endPosition, float rotationX, float rotationZ)
	{
		diceMovement.PlayGoBackToOriginalPositionAnimation(endPosition, 0.2f, endDragAnimCurve, rotationX, rotationZ, delegate
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
			{
				AfterGoBackToOriginalPositionAnimation(afterGoBackToOriginalPositionAction);
				afterGoBackToOriginalPositionAction = null;
			});
		});
	}

	public void PlayGoBackToHandFromTargetSpaceAnimation(Vector3 endPosition, float rotationX, float rotationZ)
	{
		diceMovement.PlayGoBackToOriginalPositionAnimation(endPosition, 0.2f, endDragAnimCurve, rotationX, rotationZ, delegate
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
			{
				actionInstanceOutlineHandler.ToggleOutline(toggle: true);
				actionFaceImage.raycastTarget = true;
				afterGoBackToOriginalPositionAction?.Invoke();
				afterGoBackToOriginalPositionAction = null;
				StoreTrail();
			});
		});
	}

	public void PlayAnimationAfterDiceDraw(Vector3 endPosition, float rotationX, float rotationZ, System.Action afterPositionedAction)
	{
		diceMovement.PlayAnimationAfterDiceDraw(endPosition, rotationX, rotationZ, GetAfterPositionedActionWithUpdateDiceFace(afterPositionedAction));
	}

	public void PlayAnimationAfterDiceDrawCompanionsAndEnemies(System.Action afterPositionedAction)
	{
		diceMovement.PlayAnimationAfterDiceDraw(originalPosition, diceRotationX, 0f, GetAfterPositionedActionWithUpdateDiceFace(afterPositionedAction));
	}

	private System.Action GetAfterPositionedActionWithUpdateDiceFace(System.Action afterPositionedAction)
	{
		return delegate
		{
			afterPositionedAction?.Invoke();
			UpdateDiceFace();
		};
	}

	public override void AfterGoBackToOriginalPositionAnimation(System.Action afterGoBackToOriginalPositionAction = null)
	{
		if (diceOwnerEnum == DiceOwnerEnum.PLAYER || diceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			actionInstanceOutlineHandler.ToggleOutline(toggle: true);
		}
		else if (diceOwnerEnum == DiceOwnerEnum.ENEMY && !ReferenceSingleton<GameStateManager>.Instance.IsOnChooseActionState)
		{
			actionInstanceOutlineHandler.ToggleOutline(toggle: true);
		}
		base.AfterGoBackToOriginalPositionAnimation(afterGoBackToOriginalPositionAction);
	}

	public override void DisposeAction()
	{
		base.DisposeAction();
		if (diceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			List<DiceInstance> list = new List<DiceInstance>();
			list.Add(this);
			OnDiscardUsedDices.Raise(list);
		}
		else if (diceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			ToggleActionEnabled(value: false);
			ToggleCompanionDice(value: false);
			actionInstanceOutlineHandler.ToggleOutline(toggle: false);
			GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, delegate
			{
				Discarding = false;
			});
			if (dice.DiceHasAction(seaRequiemAction))
			{
				seaRequiemAction.AddSeaRequiem(1);
			}
		}
	}

	public void DestroyDiceDisposeAction()
	{
		ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(destroyDieVFXPrefab, base.transform.position, 4f);
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(destroyDiceSFX);
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.RemoveDiceFromHand(this);
		StoreDiceInstance();
		ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
		dragging = false;
		actionFaceImage.raycastTarget = true;
		if (ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			ReferenceSingleton<InputManager>.Instance.ResetPreviousIndexes();
		}
	}

	public void TryDiscardDiceFromTraySetTrailEmissionRate()
	{
		actionInstanceTrailHandler.TryDiscardDiceFromTraySetTrailEmissionRate();
	}

	public void StoreDiceInstance()
	{
		diceVisuals.StoreDiceTrailParticles();
		StoreTrail();
		DiceVisuals.StoreDiceModel();
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
	}

	public void SetupCurrentActionInstanceForRearmReroll()
	{
		ignoreNextDisposeAction = true;
		KillTrail();
		ToggleOutline(value: false);
		dragging = false;
	}

	protected override ActionFace GetActionFace()
	{
		return dice.GetDiceFaces()[rolledDiceFaceIndex];
	}

	public void RotateToDiceFace(DiceFace diceFace, float diceRotationAnimationDuration, AnimationCurve diceRotationAnimationCurve)
	{
		int diceFaceIndex = 0;
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			if (diceFace == dice.GetDiceFaces()[i])
			{
				diceFaceIndex = i;
			}
		}
		SetDiceFaceIndex(diceFaceIndex);
		diceMovement.RotateToNewDiceFace(diceRotationAnimationDuration, diceRotationAnimationCurve);
	}

	public void UpdateRolledActionFace(int rolledDiceFaceIndex)
	{
		SetDiceFaceIndex(rolledDiceFaceIndex);
		SetDiceState(DiceState.FinishedRolling);
	}

	public void SetDiceFaceIndex(int rolledDiceFaceIndex)
	{
		disableDiscard = false;
		this.rolledDiceFaceIndex = rolledDiceFaceIndex;
		if (dice.GetDiceFaces()[rolledDiceFaceIndex].Timeless)
		{
			disableDiscard = true;
		}
		else if (dice.GetDiceFaces()[rolledDiceFaceIndex].BattleAction.Timeless)
		{
			disableDiscard = true;
		}
		else if (dice.GetDiceFaces()[rolledDiceFaceIndex].EnableSecondAction && dice.GetDiceFaces()[rolledDiceFaceIndex].SecondBattleAction.Timeless)
		{
			disableDiscard = true;
		}
	}

	public void ResetDiceTargetCastSpaceInstance()
	{
		diceTargetCastSpaceInstance = null;
	}

	public void UpdateDice(Dice dice)
	{
		this.dice = dice;
		diceVisuals.UpdateDice(dice);
	}

	public void UpdateDiceFace(bool updateOutline = true)
	{
		if (updateOutline)
		{
			actionInstanceOutlineHandler.UpdateOutlineAndMustUse();
			actionFaceImage.raycastTarget = true;
		}
		diceVisuals.UpdateDiceFaces(hideDiceFace);
		if (diceOwnerEnum == DiceOwnerEnum.ENEMY)
		{
			actionInstanceOutlineHandler.ToggleOutline(toggle: false, animation: false);
		}
		else if (diceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			if (updateOutline)
			{
				if (!actionEnabled)
				{
					actionInstanceOutlineHandler.ToggleOutline(toggle: false);
					ToggleCompanionDice(value: false);
				}
				else
				{
					actionInstanceOutlineHandler.ToggleOutline(toggle: true);
					ToggleCompanionDice(value: true);
				}
			}
		}
		else if (diceOwnerEnum == DiceOwnerEnum.PLAYER && diceState != DiceState.Rolling)
		{
			actionInstanceOutlineHandler.ToggleOutline(toggle: true);
		}
	}

	public void ToggleHideDiceFace(bool value)
	{
		hideDiceFace = value;
		if (dice != null)
		{
			UpdateDiceFace();
		}
	}

	public override void InitializeActionDescriptionPanel()
	{
		base.InitializeActionDescriptionPanel();
		string text = "";
		if (diceOwnerEnum != 0)
		{
			text = ((!(dice.DiceTier.DiceTierID == "")) ? dice.DiceTier.GetLocalizedDiceTierWithDie() : "Debug Die");
		}
		else
		{
			text = ((!dice.Mod) ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(dice.GetNameID()) : dice.GetModdedName());
			text = dice.DiceTier.GetDiceNameWithStars(text);
			if (dice.IsModdedDie())
			{
				text = text + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedCustom();
			}
		}
		if (dice is PlayerDice && (dice as PlayerDice).Magnetized)
		{
			text = text + " " + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("Magnetized");
		}
		actionDescriptionPanel.Initialize(base.actionFace, text, dice, diceOwnerEnum == DiceOwnerEnum.PLAYER, forgeDiceFace: false, isDiceInstance: true, diceOwnerEnum);
	}

	public void ToggleOutline(bool value)
	{
		actionInstanceOutlineHandler.ToggleOutline(value);
	}

	public void UpdateTransitionOutlineLayer()
	{
		(actionInstanceOutlineHandler as DiceInstanceOutlineHandler).UpdateTransitionOutlineLayer();
	}

	public void ToggleActionEnabled(bool value)
	{
		actionEnabled = value;
	}

	public void ToggleCompanionDice(bool value)
	{
		diceVisuals.ToggleCompanionDice(value);
	}

	public void SetDiceState(DiceState diceState)
	{
		this.diceState = diceState;
	}

	public void SetNewPosition(Vector3 position)
	{
		base.transform.position = position;
		SetOriginalPositionAsCurrentPosition();
		diceMovement.SetDrawTurnPositionX(position);
	}

	public void SetOriginalPosition(Vector3 position)
	{
		originalPosition = position;
		diceMovement.SetDrawTurnPositionX(position);
	}

	public void SetOriginalPositionAsCurrentPosition()
	{
		originalPosition = base.transform.position;
	}

	public void SetOriginalPositionAsCurrentPositionX()
	{
		originalPosition = new Vector2(base.transform.position.x, originalPosition.y);
	}

	public void SetOriginalDice(Dice originalDice)
	{
		this.originalDice = originalDice;
	}

	public void SetDice(Dice dice)
	{
		this.dice = dice;
	}

	public void UpdateActionValueModifier()
	{
		List<ActionValueModifier> actionValueModifiersExternal = new List<ActionValueModifier>();
		if (diceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			actionValueModifiersExternal = ReferenceSingleton<PlayerDiceHandHolder>.Instance.ActionValueModifiers;
		}
		else if (diceOwnerEnum == DiceOwnerEnum.COMPANION || diceOwnerEnum == DiceOwnerEnum.ENEMY)
		{
			actionValueModifiersExternal = actionOwner.GetComponent<UnitsDiceActivation>().ActionValueModifiers;
		}
		base.actionFace.ToggleActionValueModifier(actionValueModifiersExternal);
	}
}
